42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const ALIKE_ITEMS_PER_BLOCK = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const sum = (amounts: number[]): number =>
57	  amounts.reduce((total, amount) => total + amount, 0);
58	
59	const groupByType = (items: Item[]): Item[][] => {
60	  const groups = new Map<string, Item[]>();
61	
62	  for (const item of items) {
63	    const group = groups.get(item.type);
64	    if (group) group.push(item);
65	    else groups.set(item.type, [item]);
66	  }
67	
68	  return [...groups.values()];
69	};
70	
71	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
72	
73	const basePremiumOfGroup = (group: Item[]): number =>
74	  group.length === ALIKE_ITEMS_PER_BLOCK ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumOf));
75	
76	const CURSE_SURCHARGE_RATE = 0.5;
77	
78	const surchargeOf = (item: Item): number =>
79	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
80	
81	const quote = ({ items }: QuoteStep): StepResult => {
82	  const totalBasePremium = sum(groupByType(items).map(basePremiumOfGroup));
83	  const totalSurcharge = sum(items.map(surchargeOf));
84	
85	  return { premium: totalBasePremium + totalSurcharge + PROCESSING_FEE };
86	};
87	
88	export const runScenario = (scenario: Scenario): ScenarioResult => ({
89	  results: [quote(scenario.steps[0] as QuoteStep)],
90	});
